<?php require 'config.php';require_login();$title='Store overview';$total=(int)$pdo->query('SELECT COUNT(*) FROM medicines')->fetchColumn();$stock=(int)$pdo->query('SELECT COALESCE(SUM(quantity),0) FROM medicines')->fetchColumn();$low=(int)$pdo->query('SELECT COUNT(*) FROM medicines WHERE quantity<=reorder_level')->fetchColumn();$today=$pdo->prepare('SELECT COALESCE(SUM(total_amount),0) FROM sales WHERE DATE(sold_at)=?');$today->execute([date('Y-m-d')]);$revenue=(float)$today->fetchColumn();$recent=$pdo->query('SELECT * FROM medicines ORDER BY id DESC LIMIT 5')->fetchAll();require 'partials/header.php';?>
<div class="pagehead"><div><div class="eyebrow">STORE OVERVIEW</div><h1>Good day, <?=h($_SESSION['admin_name'])?> 👋</h1><p class="sub">A quick view of your pharmacy's inventory and sales.</p></div><a class="btn" href="sales.php">＋ Record a sale</a></div>
<div class="grid"><div class="stat"><span class="symbol">✚</span><div class="label">Medicine types</div><div class="num"><?=$total?></div><div class="hint">Products in catalogue</div></div><div class="stat"><span class="symbol">▤</span><div class="label">Units in stock</div><div class="num"><?=$stock?></div><div class="hint">Across all medicines</div></div><div class="stat"><span class="symbol">!</span><div class="label">Low stock alerts</div><div class="num"><?=$low?></div><div class="hint">At or below reorder level</div></div><div class="stat"><span class="symbol">₹</span><div class="label">Today's sales</div><div class="num">₹<?=number_format($revenue,0)?></div><div class="hint"><?=date('d M Y')?></div></div></div>
<div class="card"><div class="cardhead"><h2>Recently added medicines</h2><a class="btn secondary small" href="medicines.php">View inventory →</a></div><div class="tablewrap"><table><thead><tr><th>Medicine</th><th>Category</th><th>Batch</th><th>Expiry</th><th>Stock</th><th>Unit price</th></tr></thead><tbody><?php foreach($recent as $m):?><tr><td><strong><?=h($m['name'])?></strong></td><td><?=h($m['category'])?></td><td><?=h($m['batch_no'])?></td><td><?=h($m['expiry_date'])?></td><td><?=$m['quantity']?></td><td>₹<?=number_format((float)$m['price'],2)?></td></tr><?php endforeach?><?php if(!$recent):?><tr><td colspan="6" class="empty">No medicines in inventory. Add your first product.</td></tr><?php endif?></tbody></table></div></div><?php require 'partials/footer.php';?>
